class WalletController : ApiController
{
    private readonly IWalletService _walletService;

    public WalletController(IWalletService walletService)
    {
        _walletService = walletService;
    }

    [HttpPost]
    [Route("api/wallet/add")]
    public IHttpActionResult AddBalance(AddBalanceRequest request)
    {
        var response = _walletService.AddBalance(request);
        return Ok(response);
    }

    [HttpPost]
    [Route("api/wallet/transfer")]
    public IHttpActionResult TransferBalance(TransferBalanceRequest request)
    {
        var response = _walletService.TransferBalance(request);
        return Ok(response);
    }

    [HttpGet]
    [Route("api/wallet/balance")]
    public IHttpActionResult GetBalance(GetBalanceRequest request)
    {
        var response = _walletService.GetBalance(request);
        return Ok(response);
    }
}

